#!/usr/bin/env python3
"""Conferência de Orçamentos — pacote compacto de implantação (3 arquivos)."""
import sys, types
from pathlib import Path
SCHEMA = "-- Esquema relacional completo (criado na Etapa 1 para evitar retrabalho nas próximas)\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS filiais (\n    id     INTEGER PRIMARY KEY AUTOINCREMENT,\n    codigo TEXT NOT NULL UNIQUE,\n    nome   TEXT NOT NULL UNIQUE,\n    ativa  INTEGER NOT NULL DEFAULT 1 CHECK (ativa IN (0,1))\n);\n\n-- Uma linha por filial + dia (criada sob demanda na Etapa 2)\nCREATE TABLE IF NOT EXISTS conferencias (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    filial_id     INTEGER NOT NULL REFERENCES filiais(id) ON DELETE RESTRICT,\n    data          TEXT NOT NULL CHECK (data GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n    situacao      TEXT NOT NULL DEFAULT 'pendente'\n                  CHECK (situacao IN ('pendente','conferido','nao_util')),\n    responsavel   TEXT,\n    concluido_em  TEXT,\n    atualizado_em TEXT NOT NULL DEFAULT (datetime('now','localtime')),\n    UNIQUE (filial_id, data),\n    CHECK (situacao <> 'conferido' OR (responsavel IS NOT NULL AND trim(responsavel) <> ''))\n);\nCREATE INDEX IF NOT EXISTS idx_conf_data ON conferencias(data);\n\nCREATE TABLE IF NOT EXISTS categorias_irregularidade (\n    id    INTEGER PRIMARY KEY AUTOINCREMENT,\n    nome  TEXT NOT NULL UNIQUE,\n    ordem INTEGER NOT NULL\n);\n\n-- Uma boleta pode ter várias irregularidades (uma linha por boleta + categoria)\nCREATE TABLE IF NOT EXISTS irregularidades (\n    id             INTEGER PRIMARY KEY AUTOINCREMENT,\n    conferencia_id INTEGER NOT NULL REFERENCES conferencias(id) ON DELETE RESTRICT,\n    boleta         TEXT NOT NULL CHECK (trim(boleta) <> ''),\n    categoria_id   INTEGER NOT NULL REFERENCES categorias_irregularidade(id) ON DELETE RESTRICT,\n    observacao     TEXT,\n    criado_em      TEXT NOT NULL DEFAULT (datetime('now','localtime')),\n    UNIQUE (conferencia_id, boleta, categoria_id)\n);\nCREATE INDEX IF NOT EXISTS idx_irreg_boleta ON irregularidades(boleta);\nCREATE INDEX IF NOT EXISTS idx_irreg_cat ON irregularidades(categoria_id);\n\n-- Trilha de auditoria: preserva o histórico de alterações\nCREATE TABLE IF NOT EXISTS historico (\n    id          INTEGER PRIMARY KEY AUTOINCREMENT,\n    entidade    TEXT NOT NULL,\n    entidade_id INTEGER,\n    acao        TEXT NOT NULL,\n    detalhe     TEXT,\n    criado_em   TEXT NOT NULL DEFAULT (datetime('now','localtime'))\n);\n"
_SOURCES = {'db': '"""Acesso ao banco SQLite (relacional, persistente, compartilhado via servidor)."""\nimport os\nimport sqlite3\nfrom pathlib import Path\n\nBASE = Path(__file__).resolve().parent / "backend_runtime"\nDB_PATH = Path(os.environ.get("CONFERENCIA_DB", BASE.parent / "data" / "conferencias.db"))\n\nFILIAIS = ["03", "05", "06", "07", "08", "09", "11", "14", "16",\n           "19", "22", "24", "25", "31", "32", "33", "34"]\n\nCATEGORIAS = [\n    "FALTA PLANO ANEXADO",\n    "FALTA LIBERAÇÃO ANALISTA",\n    "FALTOU PRINT ASSINATURA OK",\n    "FALTA RUBRICA COMPROV. CRÉDITO",\n    "FALTOU FUNC ASSINAR VALE",\n    "FALTOU BOLETA COM ASS",\n    "FALTA LIBERAÇÃO SUPERVISOR",\n    "ORÇAMENTO NÃO VEIO",\n    "NADA ANEXADO",\n    "ASSINOU ERRADO",\n]\n\n\ndef conectar():\n    """Nova conexão por requisição (thread-safe). WAL permite leituras e escritas simultâneas."""\n    con = sqlite3.connect(DB_PATH, timeout=15)\n    con.row_factory = sqlite3.Row\n    con.execute("PRAGMA foreign_keys = ON")\n    con.execute("PRAGMA busy_timeout = 15000")\n    return con\n\n\ndef iniciar():\n    DB_PATH.parent.mkdir(parents=True, exist_ok=True)\n    con = conectar()\n    con.execute("PRAGMA journal_mode = WAL")\n    con.execute("PRAGMA synchronous = NORMAL")\n    con.executescript(SCHEMA)\n    for c in FILIAIS:\n        con.execute("INSERT OR IGNORE INTO filiais (codigo, nome) VALUES (?, ?)",\n                    (c, f"SHOP15 FL {c}"))\n    for i, n in enumerate(CATEGORIAS, 1):\n        con.execute("INSERT OR IGNORE INTO categorias_irregularidade (nome, ordem) VALUES (?, ?)", (n, i))\n    con.commit()\n    con.close()\n', 'routes': '"""Rotas da API. Cada etapa acrescenta rotas aqui sem alterar as anteriores."""\nimport calendar\nimport sqlite3\nfrom datetime import date, datetime\n\n\nclass ErroAPI(Exception):\n    def __init__(self, msg, status=400):\n        super().__init__(msg)\n        self.status = status\n\n\ndef filiais(con, **_):\n    linhas = con.execute("SELECT id, codigo, nome FROM filiais WHERE ativa = 1 ORDER BY codigo").fetchall()\n    return 200, [dict(r) for r in linhas]\n\n\ndef categorias(con, **_):\n    linhas = con.execute("SELECT id, nome, ordem FROM categorias_irregularidade ORDER BY ordem").fetchall()\n    return 200, [dict(r) for r in linhas]\n\n\ndef resumo(con, query=None, **_):\n    """Resumo do mês para a tela Início (a Etapa 2 passa a preencher os dados)."""\n    hoje = date.today()\n    q = query or {}\n    ano = int(q.get("ano", [hoje.year])[0])\n    mes = int(q.get("mes", [hoje.month])[0])\n    prefixo = f"{ano:04d}-{mes:02d}-%"\n    linhas = con.execute("""\n        SELECT f.id, f.nome,\n          COALESCE(SUM(c.situacao = \'conferido\'), 0) AS conferidos,\n          COALESCE(SUM(c.situacao = \'nao_util\'), 0)  AS nao_uteis,\n          (SELECT COUNT(*) FROM irregularidades i JOIN conferencias c2 ON c2.id = i.conferencia_id\n            WHERE c2.filial_id = f.id AND c2.data LIKE ?) AS irregularidades\n        FROM filiais f LEFT JOIN conferencias c ON c.filial_id = f.id AND c.data LIKE ?\n        WHERE f.ativa = 1 GROUP BY f.id ORDER BY f.codigo\n    """, (prefixo, prefixo)).fetchall()\n    return 200, {"ano": ano, "mes": mes, "filiais": [dict(r) for r in linhas]}\n\n\ndef saude(con, **_):\n    con.execute("SELECT 1")\n    return 200, {"ok": True}\n\n\n# ---------------------------------------------------------------- Etapa 2: conferências\nSITUACOES = ("pendente", "conferido", "nao_util")\n\n\ndef _inteiro(valor, nome):\n    try:\n        return int(valor)\n    except (TypeError, ValueError):\n        raise ErroAPI(f"Valor inválido para {nome}.")\n\n\ndef _filial(con, filial_id):\n    f = con.execute("SELECT id, codigo, nome FROM filiais WHERE id = ? AND ativa = 1", (filial_id,)).fetchone()\n    if not f:\n        raise ErroAPI("Filial não encontrada.", 404)\n    return f\n\n\ndef _periodo(ano, mes):\n    if not (2000 <= ano <= 2100 and 1 <= mes <= 12):\n        raise ErroAPI("Mês ou ano inválido.")\n\n\ndef _dia(con, filial_id, data):\n    r = con.execute("""\n        SELECT c.id, c.data, c.situacao, c.responsavel, c.concluido_em,\n               (SELECT COUNT(*) FROM irregularidades i WHERE i.conferencia_id = c.id) AS irregularidades\n        FROM conferencias c WHERE c.filial_id = ? AND c.data = ?""", (filial_id, data)).fetchone()\n    if r:\n        return dict(r)\n    return {"id": None, "data": data, "situacao": "pendente", "responsavel": None,\n            "concluido_em": None, "irregularidades": 0}\n\n\ndef _historico(con, entidade_id, acao, detalhe):\n    con.execute("INSERT INTO historico (entidade, entidade_id, acao, detalhe) VALUES (\'conferencia\', ?, ?, ?)",\n                (entidade_id, acao, detalhe))\n\n\ndef conferencias_mes(con, query=None, **_):\n    """Todos os dias de um mês para uma filial (dias sem registro aparecem como pendentes)."""\n    q = query or {}\n    filial = _filial(con, _inteiro((q.get("filial") or [None])[0], "filial"))\n    hoje = date.today()\n    ano = _inteiro((q.get("ano") or [hoje.year])[0], "ano")\n    mes = _inteiro((q.get("mes") or [hoje.month])[0], "mês")\n    _periodo(ano, mes)\n    prefixo = f"{ano:04d}-{mes:02d}-%"\n    linhas = con.execute("""\n        SELECT c.id, c.data, c.situacao, c.responsavel, c.concluido_em,\n               (SELECT COUNT(*) FROM irregularidades i WHERE i.conferencia_id = c.id) AS irregularidades\n        FROM conferencias c WHERE c.filial_id = ? AND c.data LIKE ?""", (filial["id"], prefixo)).fetchall()\n    por_data = {r["data"]: dict(r) for r in linhas}\n    dias = []\n    for n in range(1, calendar.monthrange(ano, mes)[1] + 1):\n        data = f"{ano:04d}-{mes:02d}-{n:02d}"\n        dias.append(por_data.get(data) or {"id": None, "data": data, "situacao": "pendente",\n                                           "responsavel": None, "concluido_em": None, "irregularidades": 0})\n    return 200, {"filial": dict(filial), "ano": ano, "mes": mes, "dias": dias}\n\n\ndef registrar_conferencia(con, corpo=None, **_):\n    """Define a situação de um dia: conferido (exige responsável), não útil, ou pendente (reabre)."""\n    c = corpo or {}\n    filial = _filial(con, _inteiro(c.get("filial_id"), "filial"))\n    try:\n        data = date.fromisoformat(str(c.get("data", "")))\n    except ValueError:\n        raise ErroAPI("Data inválida.")\n    situacao = c.get("situacao")\n    if situacao not in SITUACOES:\n        raise ErroAPI("Situação inválida.")\n    responsavel = (c.get("responsavel") or "").strip() or None\n    if situacao == "conferido":\n        if not responsavel:\n            raise ErroAPI("Informe o responsável pela conferência.")\n        if data > date.today():\n            raise ErroAPI("Não é possível marcar como conferido um dia que ainda não chegou.")\n    if len(responsavel or "") > 80:\n        raise ErroAPI("Nome do responsável muito longo (máximo 80 caracteres).")\n\n    iso = data.isoformat()\n    atual = _dia(con, filial["id"], iso)\n    if situacao == "nao_util" and atual["irregularidades"]:\n        raise ErroAPI("Este dia tem irregularidades registradas. Remova-as antes de marcá-lo como domingo/feriado.", 409)\n    if situacao == "pendente":\n        responsavel = None\n    concluido = datetime.now().strftime("%Y-%m-%d %H:%M:%S") if situacao == "conferido" else None\n    nome = {"pendente": "reaberto", "conferido": "conferido", "nao_util": "marcado como não útil"}[situacao]\n    detalhe = f"{filial[\'nome\']} · {iso} · de {atual[\'situacao\']} para {situacao}" + \\\n              (f" · responsável: {responsavel}" if responsavel else "")\n\n    if atual["id"] is None:\n        if situacao == "pendente":\n            return 200, atual\n        cur = con.execute(\n            "INSERT INTO conferencias (filial_id, data, situacao, responsavel, concluido_em) VALUES (?,?,?,?,?)",\n            (filial["id"], iso, situacao, responsavel, concluido))\n        conf_id = cur.lastrowid\n    else:\n        conf_id = atual["id"]\n        con.execute("""UPDATE conferencias SET situacao = ?, responsavel = ?, concluido_em = ?,\n                       atualizado_em = datetime(\'now\',\'localtime\') WHERE id = ?""",\n                    (situacao, responsavel, concluido, conf_id))\n    _historico(con, conf_id, nome, detalhe)\n    return 200, _dia(con, filial["id"], iso)\n\n\ndef marcar_domingos(con, corpo=None, **_):\n    """Marca como não úteis todos os domingos ainda pendentes do mês (feriados são marcados à mão)."""\n    c = corpo or {}\n    filial = _filial(con, _inteiro(c.get("filial_id"), "filial"))\n    ano, mes = _inteiro(c.get("ano"), "ano"), _inteiro(c.get("mes"), "mês")\n    _periodo(ano, mes)\n    marcados = 0\n    for n in range(1, calendar.monthrange(ano, mes)[1] + 1):\n        d = date(ano, mes, n)\n        if d.weekday() != 6:\n            continue\n        cur = con.execute("INSERT OR IGNORE INTO conferencias (filial_id, data, situacao) VALUES (?, ?, \'nao_util\')",\n                          (filial["id"], d.isoformat()))\n        marcados += cur.rowcount\n    if marcados:\n        _historico(con, None, "domingos marcados", f"{filial[\'nome\']} · {ano:04d}-{mes:02d} · {marcados} domingo(s)")\n    return 200, {"marcados": marcados}\n\n\ndef responsaveis(con, **_):\n    """Nomes já usados, do mais recente ao mais antigo (sugestões para o campo Responsável)."""\n    linhas = con.execute("""\n        SELECT responsavel FROM conferencias WHERE responsavel IS NOT NULL\n        GROUP BY responsavel ORDER BY MAX(atualizado_em) DESC LIMIT 30""").fetchall()\n    return 200, [r["responsavel"] for r in linhas]\n\n\n# ---------------------------------------------------------------- Etapa 3: irregularidades\nLIMITE_LISTA = 500\n\n\ndef _boleta(valor):\n    b = " ".join(str(valor or "").split())\n    if not b:\n        raise ErroAPI("Informe o número da boleta.")\n    if len(b) > 30:\n        raise ErroAPI("Número da boleta muito longo (máximo 30 caracteres).")\n    return b\n\n\ndef _observacao(valor):\n    o = (str(valor).strip() if valor else "") or None\n    if o and len(o) > 300:\n        raise ErroAPI("Observação muito longa (máximo 300 caracteres).")\n    return o\n\n\ndef _data_irreg(valor):\n    try:\n        d = date.fromisoformat(str(valor or ""))\n    except ValueError:\n        raise ErroAPI("Data inválida.")\n    if d.year < 2000:\n        raise ErroAPI("Data inválida.")\n    if d > date.today():\n        raise ErroAPI("Não é possível registrar irregularidade em um dia que ainda não chegou.")\n    return d.isoformat()\n\n\ndef _categoria(con, cat_id):\n    c = con.execute("SELECT id, nome FROM categorias_irregularidade WHERE id = ?", (cat_id,)).fetchone()\n    if not c:\n        raise ErroAPI("Categoria não encontrada.", 404)\n    return c\n\n\ndef _conferencia_do_dia(con, filial, iso):\n    """Devolve o id da conferência do dia (criando-a como pendente se ainda não existir)."""\n    atual = _dia(con, filial["id"], iso)\n    if atual["situacao"] == "nao_util":\n        raise ErroAPI(f"{iso[8:]}/{iso[5:7]}/{iso[:4]} está marcado como domingo/feriado em {filial[\'nome\']}. "\n                      "Reabra o dia na tela Conferências para registrar irregularidades.", 409)\n    if atual["id"] is not None:\n        return atual["id"]\n    return con.execute("INSERT INTO conferencias (filial_id, data, situacao) VALUES (?, ?, \'pendente\')",\n                       (filial["id"], iso)).lastrowid\n\n\ndef _historico_irreg(con, irr_id, acao, detalhe):\n    con.execute("INSERT INTO historico (entidade, entidade_id, acao, detalhe) VALUES (\'irregularidade\', ?, ?, ?)",\n                (irr_id, acao, detalhe))\n\n\ndef _irregularidade(con, irr_id):\n    r = con.execute("""\n        SELECT i.id, i.boleta, i.observacao, i.criado_em, i.categoria_id, k.nome AS categoria,\n               c.id AS conferencia_id, c.data, f.id AS filial_id, f.nome AS filial\n        FROM irregularidades i\n        JOIN conferencias c ON c.id = i.conferencia_id\n        JOIN filiais f ON f.id = c.filial_id\n        JOIN categorias_irregularidade k ON k.id = i.categoria_id\n        WHERE i.id = ?""", (irr_id,)).fetchone()\n    if not r:\n        raise ErroAPI("Registro não encontrado (talvez já tenha sido excluído por outra pessoa).", 404)\n    return r\n\n\ndef _resumo_irreg(r):\n    return f"{r[\'filial\']} · {r[\'data\']} · boleta {r[\'boleta\']} · {r[\'categoria\']}"\n\n\ndef listar_irregularidades(con, query=None, **_):\n    """Lista filtrada (filial, período, categoria, boleta) + contagem por categoria para as abas."""\n    q = query or {}\n    get = lambda k: ((q.get(k) or [""])[0]).strip()\n    onde, params = [], []\n    if get("filial"):\n        onde.append("c.filial_id = ?")\n        params.append(_inteiro(get("filial"), "filial"))\n    if get("ano"):\n        ano = _inteiro(get("ano"), "ano")\n        mes = _inteiro(get("mes") or 0, "mês")\n        if not (2000 <= ano <= 2100 and 0 <= mes <= 12):\n            raise ErroAPI("Mês ou ano inválido.")\n        onde.append("c.data LIKE ?")\n        params.append(f"{ano:04d}-{mes:02d}-%" if mes else f"{ano:04d}-%")\n    if get("busca"):\n        txt = get("busca").replace("\\\\", "\\\\\\\\").replace("%", "\\\\%").replace("_", "\\\\_")\n        onde.append("i.boleta LIKE ? ESCAPE \'\\\\\'")\n        params.append(f"%{txt}%")\n    base = """FROM irregularidades i\n              JOIN conferencias c ON c.id = i.conferencia_id\n              JOIN filiais f ON f.id = c.filial_id\n              JOIN categorias_irregularidade k ON k.id = i.categoria_id"""\n    filtro = (" WHERE " + " AND ".join(onde)) if onde else ""\n\n    contagem = {r["categoria_id"]: r["n"] for r in con.execute(\n        f"SELECT i.categoria_id, COUNT(*) AS n {base}{filtro} GROUP BY i.categoria_id", params)}\n\n    onde_lista, params_lista = list(onde), list(params)\n    if get("categoria"):\n        onde_lista.append("i.categoria_id = ?")\n        params_lista.append(_inteiro(get("categoria"), "categoria"))\n    filtro_lista = (" WHERE " + " AND ".join(onde_lista)) if onde_lista else ""\n    total = con.execute(f"SELECT COUNT(*) {base}{filtro_lista}", params_lista).fetchone()[0]\n    linhas = con.execute(f"""\n        SELECT i.id, i.boleta, i.observacao, i.categoria_id, k.nome AS categoria,\n               c.data, f.id AS filial_id, f.nome AS filial\n        {base}{filtro_lista}\n        ORDER BY c.data DESC, f.codigo, i.boleta, k.ordem LIMIT {LIMITE_LISTA}""", params_lista).fetchall()\n    return 200, {"total": total, "limite": LIMITE_LISTA, "por_categoria": contagem,\n                 "itens": [dict(r) for r in linhas]}\n\n\ndef criar_irregularidades(con, corpo=None, **_):\n    """Cadastro por boleta: uma boleta pode receber várias categorias de uma vez."""\n    c = corpo or {}\n    filial = _filial(con, _inteiro(c.get("filial_id"), "filial"))\n    iso = _data_irreg(c.get("data"))\n    boleta = _boleta(c.get("boleta"))\n    obs = _observacao(c.get("observacao"))\n    cats = c.get("categorias")\n    if not isinstance(cats, list) or not cats:\n        raise ErroAPI("Marque ao menos uma irregularidade.")\n    ids = list(dict.fromkeys(_inteiro(x, "categoria") for x in cats))\n    categorias_ = [_categoria(con, i) for i in ids]\n\n    conf_id = _conferencia_do_dia(con, filial, iso)\n    criadas, repetidas = [], []\n    for cat in categorias_:\n        cur = con.execute("INSERT OR IGNORE INTO irregularidades (conferencia_id, boleta, categoria_id, observacao) "\n                          "VALUES (?, ?, ?, ?)", (conf_id, boleta, cat["id"], obs))\n        if cur.rowcount:\n            criadas.append(cat["nome"])\n            _historico_irreg(con, cur.lastrowid, "registrada", f"{filial[\'nome\']} · {iso} · boleta {boleta} · {cat[\'nome\']}")\n        else:\n            repetidas.append(cat["nome"])\n    if not criadas:\n        raise ErroAPI("Esta boleta já está registrada neste dia, nesta filial, com " +\n                      ("esta irregularidade." if len(repetidas) == 1 else "estas irregularidades."), 409)\n    return 201, {"criadas": criadas, "repetidas": repetidas}\n\n\ndef editar_irregularidade(con, corpo=None, **_):\n    c = corpo or {}\n    atual = _irregularidade(con, _inteiro(c.get("id"), "registro"))\n    filial = _filial(con, _inteiro(c.get("filial_id"), "filial"))\n    iso = _data_irreg(c.get("data"))\n    boleta = _boleta(c.get("boleta"))\n    obs = _observacao(c.get("observacao"))\n    cat = _categoria(con, _inteiro(c.get("categoria_id"), "categoria"))\n\n    conf_id = _conferencia_do_dia(con, filial, iso)\n    try:\n        con.execute("""UPDATE irregularidades SET conferencia_id = ?, boleta = ?, categoria_id = ?, observacao = ?\n                       WHERE id = ?""", (conf_id, boleta, cat["id"], obs, atual["id"]))\n    except sqlite3.IntegrityError:\n        raise ErroAPI("Já existe esta mesma boleta com esta irregularidade neste dia e filial.", 409)\n    depois = _irregularidade(con, atual["id"])\n    _historico_irreg(con, atual["id"], "editada", f"de [{_resumo_irreg(atual)}] para [{_resumo_irreg(depois)}]")\n    return 200, dict(depois)\n\n\ndef excluir_irregularidade(con, query=None, **_):\n    q = query or {}\n    atual = _irregularidade(con, _inteiro((q.get("id") or [None])[0], "registro"))\n    con.execute("DELETE FROM irregularidades WHERE id = ?", (atual["id"],))\n    _historico_irreg(con, atual["id"], "excluída", _resumo_irreg(atual))\n    return 200, {"excluida": atual["id"]}\n\n\n# ---------------------------------------------------------------- Etapa 4: pesquisa e relatórios\nLIMITE_PESQUISA = 200\n\n\ndef _like(texto):\n    """Escapa %, _ e \\\\ para busca literal com LIKE ... ESCAPE \'\\\\\'."""\n    return texto.replace("\\\\", "\\\\\\\\").replace("%", "\\\\%").replace("_", "\\\\_")\n\n\ndef pesquisa(con, query=None, **_):\n    """Busca global por número de boleta: cada ocorrência (filial + dia + boleta) com todas as suas irregularidades."""\n    termo = " ".join(((query or {}).get("q") or [""])[0].split())\n    if not termo:\n        raise ErroAPI("Digite o número da boleta.")\n    if len(termo) > 30:\n        raise ErroAPI("Número da boleta muito longo (máximo 30 caracteres).")\n    linhas = con.execute(f"""\n        SELECT i.id, i.boleta, i.observacao, k.nome AS categoria, k.ordem,\n               c.id AS conferencia_id, c.data, c.situacao, f.id AS filial_id, f.nome AS filial\n        FROM irregularidades i\n        JOIN conferencias c ON c.id = i.conferencia_id\n        JOIN filiais f ON f.id = c.filial_id\n        JOIN categorias_irregularidade k ON k.id = i.categoria_id\n        WHERE i.boleta LIKE ? ESCAPE \'\\\\\'\n        ORDER BY (i.boleta = ?) DESC, c.data DESC, f.codigo, i.boleta, k.ordem""",\n        (f"%{_like(termo)}%", termo)).fetchall()\n    grupos, ordem = {}, []\n    for r in linhas:\n        chave = (r["conferencia_id"], r["boleta"])\n        if chave not in grupos:\n            grupos[chave] = {"boleta": r["boleta"], "exata": r["boleta"] == termo, "filial_id": r["filial_id"],\n                             "filial": r["filial"], "data": r["data"], "situacao": r["situacao"], "irregularidades": []}\n            ordem.append(chave)\n        grupos[chave]["irregularidades"].append(\n            {"id": r["id"], "categoria": r["categoria"], "observacao": r["observacao"]})\n    total = len(ordem)\n    return 200, {"termo": termo, "total": total, "limite": LIMITE_PESQUISA,\n                 "resultados": [grupos[k] for k in ordem[:LIMITE_PESQUISA]]}\n\n\ndef relatorio(con, query=None, **_):\n    """Relatório do período: totais, matriz filial x categoria, resumo por categoria e (no ano todo) por mês."""\n    q = query or {}\n    get = lambda k: ((q.get(k) or [""])[0]).strip()\n    hoje = date.today()\n    ano = _inteiro(get("ano") or hoje.year, "ano")\n    mes = _inteiro(get("mes") or 0, "mês")\n    if not (2000 <= ano <= 2100 and 0 <= mes <= 12):\n        raise ErroAPI("Mês ou ano inválido.")\n    prefixo = f"{ano:04d}-{mes:02d}-%" if mes else f"{ano:04d}-%"\n    filial_id = _inteiro(get("filial"), "filial") if get("filial") else None\n    cat_id = _inteiro(get("categoria"), "categoria") if get("categoria") else None\n    if cat_id is not None:\n        _categoria(con, cat_id)\n\n    sql_f = "SELECT id, codigo, nome FROM filiais WHERE ativa = 1" + (" AND id = ?" if filial_id else "") + " ORDER BY codigo"\n    filiais_ = con.execute(sql_f, (filial_id,) if filial_id else ()).fetchall()\n    if filial_id and not filiais_:\n        raise ErroAPI("Filial não encontrada.", 404)\n    cats = con.execute("SELECT id, nome FROM categorias_irregularidade ORDER BY ordem").fetchall()\n\n    por_filial = {f["id"]: {"id": f["id"], "codigo": f["codigo"], "nome": f["nome"], "conferidos": 0, "nao_uteis": 0,\n                            "boletas": 0, "irregularidades": 0, "categorias": {}} for f in filiais_}\n    for r in con.execute("""SELECT filial_id, SUM(situacao = \'conferido\') AS conf, SUM(situacao = \'nao_util\') AS nu\n                            FROM conferencias WHERE data LIKE ? GROUP BY filial_id""", (prefixo,)):\n        if r["filial_id"] in por_filial:\n            por_filial[r["filial_id"]]["conferidos"] = r["conf"] or 0\n            por_filial[r["filial_id"]]["nao_uteis"] = r["nu"] or 0\n\n    onde = "WHERE c.data LIKE ?"\n    params = [prefixo]\n    if cat_id is not None:\n        onde += " AND i.categoria_id = ?"\n        params.append(cat_id)\n    base = "FROM irregularidades i JOIN conferencias c ON c.id = i.conferencia_id"\n    for r in con.execute(f"SELECT c.filial_id, i.categoria_id, COUNT(*) AS n {base} {onde} GROUP BY c.filial_id, i.categoria_id", params):\n        f = por_filial.get(r["filial_id"])\n        if f:\n            f["categorias"][str(r["categoria_id"])] = r["n"]\n            f["irregularidades"] += r["n"]\n    for r in con.execute(f"SELECT c.filial_id, COUNT(DISTINCT c.id || \'|\' || i.boleta) AS n {base} {onde} GROUP BY c.filial_id", params):\n        if r["filial_id"] in por_filial:\n            por_filial[r["filial_id"]]["boletas"] = r["n"]\n\n    lista = list(por_filial.values())\n    por_categoria = [{"id": c["id"], "nome": c["nome"],\n                      "total": sum(f["categorias"].get(str(c["id"]), 0) for f in lista)} for c in cats]\n    if cat_id is not None:\n        por_categoria = [c for c in por_categoria if c["id"] == cat_id]\n    visiveis = set(por_filial)\n    marcadores = ",".join("?" * len(visiveis)) or "NULL"\n    por_mes = []\n    if not mes:\n        meses = {r["m"]: r for r in con.execute(f"""\n            SELECT substr(c.data, 6, 2) AS m, COUNT(*) AS irreg, COUNT(DISTINCT c.id || \'|\' || i.boleta) AS bol\n            {base} {onde} AND c.filial_id IN ({marcadores}) GROUP BY m""", params + list(visiveis))}\n        por_mes = [{"mes": n, "irregularidades": (meses.get(f"{n:02d}") or {"irreg": 0})["irreg"],\n                    "boletas": (meses.get(f"{n:02d}") or {"bol": 0})["bol"]} for n in range(1, 13)]\n    totais = {"irregularidades": sum(f["irregularidades"] for f in lista),\n              "boletas": sum(f["boletas"] for f in lista),\n              "conferidos": sum(f["conferidos"] for f in lista),\n              "nao_uteis": sum(f["nao_uteis"] for f in lista),\n              "filiais_com_irregularidade": sum(1 for f in lista if f["irregularidades"])}\n    return 200, {"ano": ano, "mes": mes, "filial_id": filial_id, "categoria_id": cat_id, "totais": totais,\n                 "categorias": [dict(c) for c in cats], "por_filial": lista,\n                 "por_categoria": por_categoria, "por_mes": por_mes}\n\n\nROTAS = {\n    ("GET", "/api/filiais"): filiais,\n    ("GET", "/api/categorias"): categorias,\n    ("GET", "/api/resumo"): resumo,\n    ("GET", "/api/saude"): saude,\n    ("GET", "/api/conferencias"): conferencias_mes,\n    ("PUT", "/api/conferencias"): registrar_conferencia,\n    ("POST", "/api/conferencias/domingos"): marcar_domingos,\n    ("GET", "/api/responsaveis"): responsaveis,\n    ("GET", "/api/irregularidades"): listar_irregularidades,\n    ("POST", "/api/irregularidades"): criar_irregularidades,\n    ("PUT", "/api/irregularidades"): editar_irregularidade,\n    ("DELETE", "/api/irregularidades"): excluir_irregularidade,\n    ("GET", "/api/pesquisa"): pesquisa,\n    ("GET", "/api/relatorio"): relatorio,\n}\n\n\ndef despachar(con, metodo, caminho, query, corpo):\n    fn = ROTAS.get((metodo, caminho.rstrip("/")))\n    if not fn:\n        raise ErroAPI("Rota não encontrada.", 404)\n    return fn(con, query=query, corpo=corpo)\n', 'xlsx': '"""Gerador mínimo de planilhas .xlsx usando só a biblioteca padrão (sem instalar nada)."""\nimport io\nimport re\nimport zipfile\nfrom datetime import date\nfrom xml.sax.saxutils import escape\n\n# Estilos (índices em cellXfs, definidos em _ESTILOS abaixo)\nNORMAL, CAB, NEG, TOTAL, TITULO, DATA, CENTRO, SUBTITULO, PCT = range(9)\n\n_CTRL = re.compile(r"[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]")\n_ORIGEM_EXCEL = date(1899, 12, 30)\n\n\ndef _nome_aba(nome):\n    return re.sub(r"[\\[\\]:*?/\\\\]", "-", nome).strip("\'")[:31] or "Planilha"\n\n\ndef _coluna(n):\n    """1 -> A, 27 -> AA"""\n    s = ""\n    while n:\n        n, r = divmod(n - 1, 26)\n        s = chr(65 + r) + s\n    return s\n\n\nclass Planilha:\n    def __init__(self, nome, larguras=None):\n        self.nome = _nome_aba(nome)\n        self.larguras = larguras or []\n        self.linhas = []          # (celulas, altura)\n        self.congelar = None      # (linhas, colunas) fixas\n        self.filtro = None        # (linha_cabecalho, ultima_linha)\n\n    def add(self, *celulas, altura=None):\n        """Cada célula: valor ou (valor, estilo). Valor: None, texto, número ou date."""\n        self.linhas.append((list(celulas), altura))\n        return len(self.linhas)\n\n    def _xml(self):\n        ncol = max([len(c) for c, _ in self.linhas] + [len(self.larguras), 1])\n        out = [\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\',\n               \'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\',\n               \'<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>\',\n               f\'<dimension ref="A1:{_coluna(ncol)}{max(len(self.linhas), 1)}"/>\']\n        if self.congelar:\n            fl, fc = self.congelar\n            topo = f"{_coluna(fc + 1)}{fl + 1}"\n            painel = "bottomRight" if fl and fc else ("bottomLeft" if fl else "topRight")\n            attrs = (f\' xSplit="{fc}"\' if fc else "") + (f\' ySplit="{fl}"\' if fl else "")\n            out.append(f\'<sheetViews><sheetView workbookViewId="0"><pane{attrs} topLeftCell="{topo}" \'\n                       f\'activePane="{painel}" state="frozen"/></sheetView></sheetViews>\')\n        else:\n            out.append(\'<sheetViews><sheetView workbookViewId="0"/></sheetViews>\')\n        out.append(\'<sheetFormatPr defaultRowHeight="15"/>\')\n        if self.larguras:\n            out.append("<cols>" + "".join(\n                f\'<col min="{i}" max="{i}" width="{w}" customWidth="1"/>\'\n                for i, w in enumerate(self.larguras, 1)) + "</cols>")\n        out.append("<sheetData>")\n        for r, (celulas, altura) in enumerate(self.linhas, 1):\n            ht = f\' ht="{altura}" customHeight="1"\' if altura else ""\n            out.append(f\'<row r="{r}"{ht}>\')\n            for c, cel in enumerate(celulas, 1):\n                valor, estilo = cel if isinstance(cel, tuple) else (cel, NORMAL)\n                if valor is None and estilo == NORMAL:\n                    continue\n                ref, s = f"{_coluna(c)}{r}", f\' s="{estilo}"\' if estilo else ""\n                if valor is None or valor == "":\n                    out.append(f\'<c r="{ref}"{s}/>\')\n                elif isinstance(valor, date):\n                    out.append(f\'<c r="{ref}"{s}><v>{(valor - _ORIGEM_EXCEL).days}</v></c>\')\n                elif isinstance(valor, bool) or not isinstance(valor, (int, float)):\n                    txt = escape(_CTRL.sub("", str(valor)))\n                    out.append(f\'<c r="{ref}"{s} t="inlineStr"><is><t xml:space="preserve">{txt}</t></is></c>\')\n                else:\n                    out.append(f\'<c r="{ref}"{s}><v>{valor}</v></c>\')\n            out.append("</row>")\n        out.append("</sheetData>")\n        if self.filtro and self.filtro[1] > self.filtro[0]:\n            out.append(f\'<autoFilter ref="A{self.filtro[0]}:{_coluna(ncol)}{self.filtro[1]}"/>\')\n        out.append(\'<pageMargins left="0.5" right="0.5" top="0.6" bottom="0.6" header="0.3" footer="0.3"/>\')\n        out.append(\'<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>\')\n        out.append("</worksheet>")\n        return "".join(out)\n\n\n_ESTILOS = """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\n<numFmts count="1"><numFmt numFmtId="164" formatCode="dd/mm/yyyy"/></numFmts>\n<fonts count="5">\n<font><sz val="11"/><name val="Calibri"/></font>\n<font><b/><sz val="11"/><name val="Calibri"/></font>\n<font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font>\n<font><b/><sz val="14"/><name val="Calibri"/></font>\n<font><i/><sz val="10"/><color rgb="FF595959"/><name val="Calibri"/></font>\n</fonts>\n<fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>\n<fill><patternFill patternType="solid"><fgColor rgb="FF305496"/><bgColor indexed="64"/></patternFill></fill></fills>\n<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border>\n<border><left/><right/><top style="thin"><color auto="1"/></top><bottom/><diagonal/></border></borders>\n<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>\n<cellXfs count="9">\n<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>\n<xf numFmtId="0" fontId="2" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>\n<xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/>\n<xf numFmtId="0" fontId="1" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1"/>\n<xf numFmtId="0" fontId="3" fillId="0" borderId="0" xfId="0" applyFont="1"/>\n<xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1" applyAlignment="1"><alignment horizontal="center"/></xf>\n<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center"/></xf>\n<xf numFmtId="0" fontId="4" fillId="0" borderId="0" xfId="0" applyFont="1"/>\n<xf numFmtId="10" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/>\n</cellXfs>\n<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>\n</styleSheet>"""\n\n\ndef gerar(planilhas):\n    """Recebe uma lista de Planilha e devolve os bytes do arquivo .xlsx."""\n    n = len(planilhas)\n    tipos = (\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\'\n             \'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\'\n             \'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\'\n             \'<Default Extension="xml" ContentType="application/xml"/>\'\n             \'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\'\n             \'<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>\'\n             + "".join(f\'<Override PartName="/xl/worksheets/sheet{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>\'\n                       for i in range(1, n + 1)) + "</Types>")\n    raiz = (\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\'\n            \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            \'<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>\'\n            \'</Relationships>\')\n    livro = (\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\'\n             \'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" \'\n             \'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>\'\n             + "".join(f\'<sheet name="{escape(p.nome, {chr(34): "&quot;"})}" sheetId="{i}" r:id="rId{i}"/>\'\n                       for i, p in enumerate(planilhas, 1)) + "</sheets></workbook>")\n    rels = (\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\'\n            \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            + "".join(f\'<Relationship Id="rId{i}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{i}.xml"/>\'\n                      for i in range(1, n + 1))\n            + f\'<Relationship Id="rId{n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>\'\n            \'</Relationships>\')\n    buf = io.BytesIO()\n    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:\n        z.writestr("[Content_Types].xml", tipos)\n        z.writestr("_rels/.rels", raiz)\n        z.writestr("xl/workbook.xml", livro)\n        z.writestr("xl/_rels/workbook.xml.rels", rels)\n        z.writestr("xl/styles.xml", _ESTILOS)\n        for i, p in enumerate(planilhas, 1):\n            z.writestr(f"xl/worksheets/sheet{i}.xml", p._xml())\n    return buf.getvalue()\n', 'exportar': '"""Exportação para Excel (.xlsx). Etapa 5a. Usa as mesmas regras e filtros das telas."""\nimport calendar\nfrom datetime import date, datetime\n\nimport routes\nimport xlsx\nfrom routes import ErroAPI\n\nMESES = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",\n         "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"]\nDIAS = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo"]\nSITUACAO = {"pendente": "Pendente", "conferido": "Conferido", "nao_util": "Domingo/feriado"}\nTITULO = "Conferência de Orçamentos — SHOP15"\n\n\ndef _get(q, chave):\n    return ((q.get(chave) or [""])[0]).strip()\n\n\ndef _periodo(q, mes_obrigatorio=False):\n    hoje = date.today()\n    ano = routes._inteiro(_get(q, "ano") or hoje.year, "ano")\n    mes = routes._inteiro(_get(q, "mes") or (hoje.month if mes_obrigatorio else 0), "mês")\n    if not (2000 <= ano <= 2100 and 0 <= mes <= 12) or (mes_obrigatorio and not mes):\n        raise ErroAPI("Mês ou ano inválido.")\n    return ano, mes\n\n\ndef _rotulo_periodo(ano, mes):\n    return f"{MESES[mes - 1]} de {ano}" if mes else f"Ano de {ano}"\n\n\ndef _sufixo(ano, mes):\n    return f"{ano:04d}-{mes:02d}" if mes else f"{ano:04d}"\n\n\ndef _data_hora(texto):\n    try:\n        return datetime.strptime(texto, "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y %H:%M")\n    except (TypeError, ValueError):\n        return texto or ""\n\n\ndef _iso(texto):\n    return date(int(texto[:4]), int(texto[5:7]), int(texto[8:10]))\n\n\n# ---------------------------------------------------------------- Relatório\ndef relatorio(con, q):\n    _, r = routes.relatorio(con, query=q)\n    ano, mes, t = r["ano"], r["mes"], r["totais"]\n    cats = [c for c in r["categorias"] if not r["categoria_id"] or c["id"] == r["categoria_id"]]\n    periodo = _rotulo_periodo(ano, mes)\n    escopo = " · ".join([r["por_filial"][0]["nome"] if r["filial_id"] else "Todas as filiais",\n                         cats[0]["nome"] if r["categoria_id"] else "Todas as categorias"])\n    sub = f"{periodo} · {escopo}"\n\n    p1 = xlsx.Planilha("Filial x categoria", [18] + [15] * len(cats) + [12, 12, 14])\n    p1.add((f"{TITULO} — Irregularidades por filial e categoria", xlsx.TITULO))\n    p1.add((sub, xlsx.SUBTITULO))\n    p1.add()\n    cab = p1.add(*[(h, xlsx.CAB) for h in ["Filial"] + [c["nome"] for c in cats] + ["Total", "Boletas", "Dias conferidos"]],\n                 altura=48)\n    for f in r["por_filial"]:\n        p1.add(f["nome"], *[f["categorias"].get(str(c["id"]), 0) for c in cats],\n               (f["irregularidades"], xlsx.NEG), f["boletas"], f["conferidos"])\n    fim = len(p1.linhas)\n    tot_cat = {c["id"]: c["total"] for c in r["por_categoria"]}\n    p1.add(("Total", xlsx.TOTAL), *[(tot_cat.get(c["id"], 0), xlsx.TOTAL) for c in cats],\n           (t["irregularidades"], xlsx.TOTAL), (t["boletas"], xlsx.TOTAL), (t["conferidos"], xlsx.TOTAL))\n    p1.congelar, p1.filtro = (cab, 1), (cab, fim)\n\n    p2 = xlsx.Planilha("Por categoria", [36, 14, 14])\n    p2.add((f"{TITULO} — Resumo por categoria", xlsx.TITULO))\n    p2.add((sub, xlsx.SUBTITULO))\n    p2.add()\n    cab2 = p2.add(*[(h, xlsx.CAB) for h in ["Categoria", "Irregularidades", "% do total"]], altura=30)\n    soma = sum(c["total"] for c in r["por_categoria"])\n    for c in r["por_categoria"]:\n        p2.add(c["nome"], c["total"], ((c["total"] / soma) if soma else 0, xlsx.PCT))\n    p2.add(("Total", xlsx.TOTAL), (soma, xlsx.TOTAL), (1 if soma else 0, xlsx.PCT))\n    p2.congelar = (cab2, 0)\n\n    folhas = [p1, p2]\n    if r["por_mes"]:\n        p3 = xlsx.Planilha("Por mês", [16, 16, 12])\n        p3.add((f"{TITULO} — Evolução mensal", xlsx.TITULO))\n        p3.add((sub, xlsx.SUBTITULO))\n        p3.add()\n        cab3 = p3.add(*[(h, xlsx.CAB) for h in ["Mês", "Irregularidades", "Boletas"]], altura=30)\n        for m in r["por_mes"]:\n            p3.add(MESES[m["mes"] - 1], m["irregularidades"], m["boletas"])\n        p3.add(("Total", xlsx.TOTAL), (sum(m["irregularidades"] for m in r["por_mes"]), xlsx.TOTAL),\n               (sum(m["boletas"] for m in r["por_mes"]), xlsx.TOTAL))\n        p3.congelar = (cab3, 0)\n        folhas.append(p3)\n    return f"relatorio-{_sufixo(ano, mes)}.xlsx", xlsx.gerar(folhas)\n\n\n# ---------------------------------------------------------- Irregularidades\ndef irregularidades(con, q):\n    onde, params = [], []\n    if _get(q, "filial"):\n        onde.append("c.filial_id = ?")\n        params.append(routes._inteiro(_get(q, "filial"), "filial"))\n    if _get(q, "categoria"):\n        onde.append("i.categoria_id = ?")\n        params.append(routes._inteiro(_get(q, "categoria"), "categoria"))\n    ano = mes = None\n    if _get(q, "ano"):\n        ano, mes = _periodo(q)\n        onde.append("c.data LIKE ?")\n        params.append(f"{ano:04d}-{mes:02d}-%" if mes else f"{ano:04d}-%")\n    if _get(q, "busca"):\n        txt = _get(q, "busca").replace("\\\\", "\\\\\\\\").replace("%", "\\\\%").replace("_", "\\\\_")\n        onde.append("i.boleta LIKE ? ESCAPE \'\\\\\'")\n        params.append(f"%{txt}%")\n    filtro = (" WHERE " + " AND ".join(onde)) if onde else ""\n    linhas = con.execute(f"""\n        SELECT c.data, f.nome AS filial, i.boleta, k.nome AS categoria, i.observacao, i.criado_em\n        FROM irregularidades i\n        JOIN conferencias c ON c.id = i.conferencia_id\n        JOIN filiais f ON f.id = c.filial_id\n        JOIN categorias_irregularidade k ON k.id = i.categoria_id\n        {filtro} ORDER BY c.data, f.codigo, i.boleta, k.ordem""", params).fetchall()\n\n    p = xlsx.Planilha("Irregularidades", [12, 18, 16, 34, 45, 18])\n    cab = p.add(*[(h, xlsx.CAB) for h in ["Data", "Filial", "Boleta", "Categoria", "Observação", "Registrado em"]],\n                altura=30)\n    for l in linhas:\n        p.add((_iso(l["data"]), xlsx.DATA), l["filial"], str(l["boleta"]), l["categoria"],\n              l["observacao"] or "", _data_hora(l["criado_em"]))\n    p.congelar, p.filtro = (cab, 0), (cab, len(p.linhas))\n    return f"irregularidades-{_sufixo(ano, mes) if ano else \'todas\'}.xlsx", xlsx.gerar([p])\n\n\n# ------------------------------------------------------------- Conferências\ndef conferencias(con, q):\n    ano, mes = _periodo(q, mes_obrigatorio=False)\n    if not _get(q, "ano") and not _get(q, "mes"):\n        ano, mes = _periodo(q, mes_obrigatorio=True)\n    filial_id = routes._inteiro(_get(q, "filial"), "filial") if _get(q, "filial") else None\n    sql = "SELECT id, codigo, nome FROM filiais WHERE ativa = 1" + (" AND id = ?" if filial_id else "") + " ORDER BY codigo"\n    filiais = con.execute(sql, (filial_id,) if filial_id else ()).fetchall()\n    if not filiais:\n        raise ErroAPI("Filial não encontrada.", 404)\n\n    prefixo = f"{ano:04d}-{mes:02d}-%" if mes else f"{ano:04d}-%"\n    reg = {(r["filial_id"], r["data"]): r for r in con.execute("""\n        SELECT c.filial_id, c.data, c.situacao, c.responsavel, c.concluido_em,\n               (SELECT COUNT(*) FROM irregularidades i WHERE i.conferencia_id = c.id) AS irreg\n        FROM conferencias c WHERE c.data LIKE ?""", (prefixo,))}\n    if mes:\n        datas = [date(ano, mes, d) for d in range(1, calendar.monthrange(ano, mes)[1] + 1)]\n    else:\n        datas = [date.fromordinal(n) for n in range(date(ano, 1, 1).toordinal(), date(ano, 12, 31).toordinal() + 1)]\n    hoje = date.today()\n    periodo = _rotulo_periodo(ano, mes)\n    escopo = filiais[0]["nome"] if filial_id else "Todas as filiais"\n\n    detalhe = xlsx.Planilha("Conferências", [18, 12, 15, 17, 24, 18, 14])\n    cab = detalhe.add(*[(h, xlsx.CAB) for h in ["Filial", "Data", "Dia da semana", "Situação", "Responsável",\n                                                  "Concluído em", "Irregularidades"]], altura=30)\n    for f in filiais:\n        for d in datas:\n            r = reg.get((f["id"], d.isoformat()))\n            detalhe.add(f["nome"], (d, xlsx.DATA), DIAS[d.weekday()], SITUACAO[r["situacao"]] if r else "Pendente",\n                        (r["responsavel"] if r else "") or "", _data_hora(r["concluido_em"]) if r else "",\n                        r["irreg"] if r else 0)\n    detalhe.congelar, detalhe.filtro = (cab, 0), (cab, len(detalhe.linhas))\n\n    folhas = [detalhe]\n    if mes:\n        cal = xlsx.Planilha("Calendário", [18] + [4.5] * len(datas) + [11, 18])\n        cal.add((f"{TITULO} — Calendário de conferências", xlsx.TITULO))\n        cal.add((f"{periodo} · {escopo} · C = conferido · — = domingo/feriado · vazio = pendente",\n                 xlsx.SUBTITULO))\n        cal.add()\n        cab_c = cal.add(*[(h, xlsx.CAB) for h in ["Filial"] + [d.day for d in datas] + ["Conferidos", "Pendentes (até hoje)"]],\n                        altura=45)\n        for f in filiais:\n            conf = pend = 0\n            celulas = [f["nome"]]\n            for d in datas:\n                r = reg.get((f["id"], d.isoformat()))\n                s = r["situacao"] if r else "pendente"\n                celulas.append(("C" if s == "conferido" else "—" if s == "nao_util" else "", xlsx.CENTRO))\n                conf += s == "conferido"\n                pend += s == "pendente" and d <= hoje\n            cal.add(*celulas, (conf, xlsx.CENTRO), (pend, xlsx.CENTRO))\n        cal.congelar = (cab_c, 1)\n        folhas.insert(0, cal)\n    nome = f"conferencias-{_sufixo(ano, mes)}" + (f"-filial-{filiais[0][\'codigo\']}" if filial_id else "") + ".xlsx"\n    return nome, xlsx.gerar(folhas)\n\n\nEXPORTACOES = {\n    "/exportar/relatorio": relatorio,\n    "/exportar/irregularidades": irregularidades,\n    "/exportar/conferencias": conferencias,\n}\n\n\ndef gerar(con, caminho, query):\n    fn = EXPORTACOES.get(caminho.rstrip("/"))\n    if not fn:\n        raise ErroAPI("Exportação não encontrada.", 404)\n    return fn(con, query or {})\n'}
for _name, _source in _SOURCES.items():
    _module = types.ModuleType(_name)
    _module.__file__ = str(Path(__file__).resolve().parent / "backend_runtime" / (_name + ".py"))
    _module.SCHEMA = SCHEMA
    sys.modules[_name] = _module
    exec(compile(_source, _module.__file__, "exec"), _module.__dict__)
# Execute o servidor no contexto principal, mantendo a estrutura original das rotas.
exec(compile('"""Servidor web + API JSON. Usa apenas a biblioteca padrão do Python (sem instalar pacotes)."""\nimport json\nimport mimetypes\nimport socket\nimport sys\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom pathlib import Path\nfrom urllib.parse import urlparse, parse_qs\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nimport db\nimport exportar\nimport routes\n\nFRONT = Path(__file__).resolve().parent.resolve()\nPORTA = 8080\n\n\nclass Handler(BaseHTTPRequestHandler):\n    server_version = "Conferencia/1.0"\n\n    def log_message(self, fmt, *args):\n        pass\n\n    def _json(self, dados, status=200):\n        corpo = json.dumps(dados, ensure_ascii=False).encode("utf-8")\n        self.send_response(status)\n        self.send_header("Content-Type", "application/json; charset=utf-8")\n        self.send_header("Content-Length", str(len(corpo)))\n        self.send_header("Cache-Control", "no-store")\n        self.end_headers()\n        self.wfile.write(corpo)\n\n    def _api(self, metodo):\n        url = urlparse(self.path)\n        con = db.conectar()\n        try:\n            corpo = None\n            tam = int(self.headers.get("Content-Length") or 0)\n            if tam:\n                corpo = json.loads(self.rfile.read(tam).decode("utf-8"))\n            status, dados = routes.despachar(con, metodo, url.path, parse_qs(url.query), corpo)\n            con.commit()\n            self._json(dados, status)\n        except routes.ErroAPI as e:\n            con.rollback()\n            self._json({"erro": str(e)}, e.status)\n        except Exception as e:\n            con.rollback()\n            print("Erro:", repr(e))\n            self._json({"erro": "Erro interno do servidor."}, 500)\n        finally:\n            con.close()\n\n    def _exportar(self):\n        url = urlparse(self.path)\n        con = db.conectar()\n        try:\n            nome, dados = exportar.gerar(con, url.path, parse_qs(url.query))\n            self.send_response(200)\n            self.send_header("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n            self.send_header("Content-Disposition", f\'attachment; filename="{nome}"\')\n            self.send_header("Content-Length", str(len(dados)))\n            self.send_header("Cache-Control", "no-store")\n            self.end_headers()\n            self.wfile.write(dados)\n        except routes.ErroAPI as e:\n            self._json({"erro": str(e)}, e.status)\n        except Exception as e:\n            print("Erro na exportação:", repr(e))\n            self._json({"erro": "Não foi possível gerar a planilha."}, 500)\n        finally:\n            con.close()\n\n    def _estatico(self):\n        caminho = urlparse(self.path).path\n        if caminho in ("", "/"):\n            caminho = "/index.html"\n        alvo = (FRONT / caminho.lstrip("/")).resolve()\n        if FRONT not in alvo.parents or not alvo.is_file():\n            alvo = FRONT / "index.html"\n        dados = alvo.read_bytes()\n        tipo = mimetypes.guess_type(alvo.name)[0] or "application/octet-stream"\n        if tipo.startswith("text") or tipo.endswith("javascript"):\n            tipo += "; charset=utf-8"\n        self.send_response(200)\n        self.send_header("Content-Type", tipo)\n        self.send_header("Content-Length", str(len(dados)))\n        self.send_header("Cache-Control", "no-cache")\n        self.end_headers()\n        self.wfile.write(dados)\n\n    def do_GET(self):\n        if self.path.startswith("/api/"):\n            self._api("GET")\n        elif self.path.startswith("/exportar/"):\n            self._exportar()\n        else:\n            self._estatico()\n\n    def do_POST(self):\n        self._api("POST")\n\n    def do_PUT(self):\n        self._api("PUT")\n\n    def do_DELETE(self):\n        self._api("DELETE")\n\n\ndef ip_local():\n    try:\n        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n        s.connect(("10.255.255.255", 1))\n        ip = s.getsockname()[0]\n        s.close()\n        return ip\n    except Exception:\n        return "IP-DO-SERVIDOR"\n\n\nif __name__ == "__main__":\n    db.iniciar()\n    porta = int(sys.argv[1]) if len(sys.argv) > 1 else PORTA\n    srv = ThreadingHTTPServer(("0.0.0.0", porta), Handler)\n    print("=" * 58)\n    print(" Conferência de Orçamentos — servidor ativo")\n    print(f" Neste computador:    http://localhost:{porta}")\n    print(f" Outros computadores: http://{ip_local()}:{porta}")\n    print(" Para encerrar: Ctrl+C")\n    print("=" * 58)\n    try:\n        srv.serve_forever()\n    except KeyboardInterrupt:\n        print("\\nServidor encerrado.")\n', str(Path(__file__).resolve()), "exec"), {"__name__": "__main__", "__file__": str(Path(__file__).resolve())})
